import{_ as e,c as r,o as h,ah as i}from"./chunks/framework.Dnh4IO1K.js";const b=JSON.parse('{"title":"觀","description":"周易集解 - 觀","frontmatter":{"title":"觀","description":"周易集解 - 觀"},"headers":[],"relativePath":"classics/jijie/020.md","filePath":"classics/jijie/020.md"}'),l={name:"classics/jijie/020.md"};function n(d,a,p,t,s,c){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="觀" tabindex="-1">觀 <a class="header-anchor" href="#觀" aria-label="Permalink to “觀”">​</a></h1><h2 id="觀-1" tabindex="-1">觀 <a class="header-anchor" href="#觀-1" aria-label="Permalink to “觀”">​</a></h2><h2 id="卦辭" tabindex="-1">卦辭 <a class="header-anchor" href="#卦辭" aria-label="Permalink to “卦辭”">​</a></h2><p>觀，盥而不薦，有孚顒若。</p><h2 id="卦辭注" tabindex="-1">卦辭注 <a class="header-anchor" href="#卦辭注" aria-label="Permalink to “卦辭注”">​</a></h2><p>《序卦》曰：物大然後可觀也。故受之以觀。</p><p>崔憬曰：言德業大者，可以觀政於人，故受之以觀也。</p><p>鄭玄曰：坤為地，為眾。巽為木，為風。九五，天子之爻。互體有艮。艮為鬼門，又為宮闕。地上有木，而為鬼門宮闕者，天子宗廟之象也。</p><p>王弼曰：王道之可觀者，莫盛乎宗廟。宗廟之可觀者，莫盛乎盥也。至薦簡略，不足復觀，故｢觀盥而不薦｣也。</p><p>馬融曰：盥者，進爵灌地，以降神也。此是祭祀盛時，及神降薦牲，其禮簡略，不足觀也。國之大事，唯祀與戎。王道可觀，在於祭祀。祭祀之盛，莫過初盥降神。故孔子曰：禘自既灌而往者，吾不欲觀之矣。此言及薦簡略，則不足觀也。以下觀上，見其至盛之禮，萬民信敬，故雲｢有孚顒若｣。孚，信。顒，敬也。</p><p>案：鬼神害盈，禍淫福善。若人君修德，至誠感神，則黍稷非馨，明德惟馨。故｢觀盥而不觀薦｣，饗其誠信者也。斯即東鄰殺牛，不如西鄰之禴祭，實受其福，是其義也。</p><h2 id="彖" tabindex="-1">彖 <a class="header-anchor" href="#彖" aria-label="Permalink to “彖”">​</a></h2><p>《彖》曰：大觀在上，順而巽，中正以觀天下。觀，盥而不薦，有孚顒若，下觀而化也。觀天之神道，而四時不忒。聖人以神道設教，而天下服矣。</p><h2 id="彖傳注" tabindex="-1">彖傳注 <a class="header-anchor" href="#彖傳注" aria-label="Permalink to “彖傳注”">​</a></h2><p>蜀才曰：此本乾卦。</p><p>案：柔小浸長，剛大在上，其德可觀，故曰｢大觀在上｣也。</p><p>虞翻曰：謂陽息臨二，直方大。臨者，大也。在觀上，故稱大觀。順，坤也。中正謂五。五以天神道觀示天下，鹹服其化，賓於王庭。</p><p>虞翻曰：觀，反臨也。以五陽觀示坤民，故稱觀。盥，沃盥。薦，羞牲也。孚，信，謂五。顒顒，君德，有威容貌。若，順也。坎為水，坤為器，艮手臨坤，坎水沃之，盥之象也。故｢觀盥而不薦｣。孔子曰：禘自既灌，吾不欲觀之矣。巽為進退，容止可觀，進退可度，則下觀其德而順其化。上之三，五在坎中，故｢有孚顒若，下觀而化｣。《詩》曰：顒顒卬卬，如珪如璋。君德之義也。</p><p>虞翻曰：忒，差也。神道謂五。臨，震兌為春秋，三上易位，坎冬離夏，日月象正。故四時不忒。</p><p>虞翻曰：聖人謂乾，退藏於密，而齊於巽，以神明其德教，故｢聖人設教｣，坤民順從，而天下服矣。</p><h2 id="象" tabindex="-1">象 <a class="header-anchor" href="#象" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：風行地上，觀。先王以省方觀民設教。</p><h2 id="象傳注" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注" aria-label="Permalink to “象傳注”">​</a></h2><p>《九家易》曰：先王謂五。應天順民，受命之王也。風行地上，草木必偃，枯藁朽腐，獨不從風，謂應外之爻。天地氣絕，陰陽所去，象不化之民，五刑所加，故以省察四方，觀視民俗，而設其教也。言先王德化，光被四表，有不賓之民，不從法令，以五刑加之，以齊德教也。</p><h2 id="初六" tabindex="-1">初六 <a class="header-anchor" href="#初六" aria-label="Permalink to “初六”">​</a></h2><p>初六，童觀，小人無咎，君子吝。</p><h2 id="初六注" tabindex="-1">初六注 <a class="header-anchor" href="#初六注" aria-label="Permalink to “初六注”">​</a></h2><p>虞翻曰：艮為童。陰，小人。陽，君子。初位賤，以小人承君子，故無咎。陽伏陰下，故君子吝矣。</p><h2 id="象-1" tabindex="-1">象 <a class="header-anchor" href="#象-1" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：初六童觀，小人道也。</p><h2 id="象傳注-1" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-1" aria-label="Permalink to “象傳注”">​</a></h2><p>王弼曰：失位處下，最遠朝美，無所鑒見，故曰童觀。處大觀之時，而童觀趣順而已。小人為之，無可咎責。君子為之，鄙吝之道。</p><h2 id="六二" tabindex="-1">六二 <a class="header-anchor" href="#六二" aria-label="Permalink to “六二”">​</a></h2><p>六二，闚觀，利女貞。</p><h2 id="六二注" tabindex="-1">六二注 <a class="header-anchor" href="#六二注" aria-label="Permalink to “六二注”">​</a></h2><p>虞翻曰：臨兌為女。竊觀稱闚，兌女反成巽。巽四五得正，故利女貞。艮為宮室，坤為闔戶，小人而應五。故闚觀女貞利，不淫視也。</p><h2 id="象-2" tabindex="-1">象 <a class="header-anchor" href="#象-2" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：闚觀女貞，亦可醜也。</p><h2 id="象傳注-2" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-2" aria-label="Permalink to “象傳注”">​</a></h2><p>侯果曰：得位居中，上應於五。闚觀朝美，不能大觀。處大觀之時，而為闚觀。女正則利，君子則醜也。</p><p>案：六二離爻，離為目，又為中女。外互體艮，艮為門。闕女目近門，闚觀之象也。</p><h2 id="六三" tabindex="-1">六三 <a class="header-anchor" href="#六三" aria-label="Permalink to “六三”">​</a></h2><p>六三，觀我生，進退。</p><h2 id="六三注" tabindex="-1">六三注 <a class="header-anchor" href="#六三注" aria-label="Permalink to “六三注”">​</a></h2><p>虞翻曰：坤為我，臨震為生。生，謂坤生民也；巽為進退，故｢觀我生進退｣。臨震進之五，得正居中，故《象》曰｢未失道｣。</p><h2 id="象-3" tabindex="-1">象 <a class="header-anchor" href="#象-3" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：觀我生進退，未失道也。</p><h2 id="象傳注-3" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-3" aria-label="Permalink to “象傳注”">​</a></h2><p>荀爽曰：我，謂五也。生者，教化生也。三欲進觀於五，四既在前，而三故退，未失道也。</p><h2 id="六四" tabindex="-1">六四 <a class="header-anchor" href="#六四" aria-label="Permalink to “六四”">​</a></h2><p>六四：觀國之光，利用賓於王。</p><h2 id="六四注" tabindex="-1">六四注 <a class="header-anchor" href="#六四注" aria-label="Permalink to “六四注”">​</a></h2><p>虞翻曰：坤為國。臨陽至二，天下文明。反上成觀，進顯天位，故觀國之光。王謂五陽。陽尊賓坤。坤為用、為臣，四在王庭，賓事於五。故｢利用賓於王｣矣。《詩》曰：莫敢不來賓，莫敢不來王。是其義也。</p><h2 id="象-4" tabindex="-1">象 <a class="header-anchor" href="#象-4" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：觀國之光，尚賓也。</p><h2 id="象傳注-4" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-4" aria-label="Permalink to “象傳注”">​</a></h2><p>崔憬曰：得位比尊，承於王者。職在搜揚國俊，賓薦王庭，故以進賢為尚賓也。</p><h2 id="九五" tabindex="-1">九五 <a class="header-anchor" href="#九五" aria-label="Permalink to “九五”">​</a></h2><p>九五：觀我生，君子無咎。</p><h2 id="九五注" tabindex="-1">九五注 <a class="header-anchor" href="#九五注" aria-label="Permalink to “九五注”">​</a></h2><p>虞翻曰：我，身也，謂我生。生，謂生民。震生象。反坤，為死喪。嫌非生民，故不言民。陽為君子，在臨二，失位之五，得道處中，故君子無咎矣。</p><h2 id="象-5" tabindex="-1">象 <a class="header-anchor" href="#象-5" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：觀我生，觀民也。</p><h2 id="象傳注-5" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-5" aria-label="Permalink to “象傳注”">​</a></h2><p>王弼曰：觀我生，自觀其道也。為眾觀之主，當宣文化，光於四表，上之化下，猶風之靡草。百姓有過，在予一人。君子風著，已乃無咎。欲察已道，當觀民也。</p><p>虞翻曰：坤為民，謂三也。坤體成，故觀民也。</p><h2 id="上九" tabindex="-1">上九 <a class="header-anchor" href="#上九" aria-label="Permalink to “上九”">​</a></h2><p>上九，觀其生，君子無咎。</p><h2 id="上九注" tabindex="-1">上九注 <a class="header-anchor" href="#上九注" aria-label="Permalink to “上九注”">​</a></h2><p>虞翻曰：應在三，三體臨震，故觀其生。君子謂三，之三得正，故無咎矣。</p><h2 id="象-6" tabindex="-1">象 <a class="header-anchor" href="#象-6" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：觀其生，志未平也。</p><h2 id="象傳注-6" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-6" aria-label="Permalink to “象傳注”">​</a></h2><p>王弼曰：觀其生，為人所觀也。最處上，極天下所觀者也。處天下所觀之地，其志未為平易，不可不慎。故君子德見，乃得無咎。生，猶動出也。</p><p>虞翻曰：坎為志，為平，上來之三，故志未平矣。</p>',75)])])}const m=e(l,[["render",n]]);export{b as __pageData,m as default};
